for w,g,b in [('depuis','Указано, что боль началась вчера и продолжается сейчас.','Прошедший эпизод с длительностью и просьба о записи имеют другое значение. Здесь нужно продолжающееся состояние.'),('symptome','Названо слово симптом в учебной реплике.','Запись и билет — другие понятия. Слово не устанавливает диагноз.'),('cabinet-medical','Назван кабинет врача как место приёма.','Вокзал и кафе — другие места, не кабинет врача.'),('douleur','Названа боль в спине.','Час приёма и просьба записаться не называют место боли.'),('il-y-a-ago','Указано двадцать минут назад.','Уже двадцать минут описывает продолжающийся период, в течение двадцати минут — длительность. Здесь нужно время события в прошлом.'),('ordonnance','Назван врачебный рецепт как документ.','Симптом — самоописание, запись — назначенное время, а не запрошенный документ.'),('consigne','Названо само указание.','Рецепт — документ, встреча — назначенное время. Они не являются словом указание.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

