order(s,[U],['jai-mal','tete','depuis','hier','je-voudrais','prendre-rendez-vous','medecin'],[],'Соберите: голова болит со вчерашнего дня. Мне бы хотелось записаться к врачу. Сначала самоописание и начало, затем просьба о записи.',[('J’ai mal','жэ ма́ль'),('à la tête','а ла тэ́т'),('depuis hier.','дёпюи йэ́р'),('Je voudrais','жё вудрэ́'),('prendre rendez-vous','пра(н)др ра(н)дэ ву́'),('avec le médecin.','авэк лё мэдсэ́(н)')],'J’ai mal à la tête depuis hier. Je voudrais prendre rendez-vous avec le médecin.','жэ маль а ла тэт дёпюи йэ́р. жё вудрэ пра(н)др ра(н)дэ ву авэк лё мэдсэ́(н).','Сохранены место и временное начало самоописания, затем просьба о записи.','После боли в голове поставьте со вчерашнего дня, затем вежливую запись к врачу.')
page(s,[('Продолжается сейчас',['В показанном самоописании настоящее время вместе с указанием начала связывает состояние с прошлым и продолжением сейчас. Это языковая модель, а не диагноз.'],[W['depuis']['example']]),('Указанная длительность',['Предлог длительности повторяется с выбранной прошедшей формой боли. Нынешнее состояние в примере уточняется отдельной фразой.'],[ex('J’ai eu mal au dos pendant vingt minutes. Maintenant, je n’ai pas mal au dos.','Спина болела двадцать минут. Теперь спина не болит.','жэ ю маль о до па(н)да(н) вэ(н) миню́т. мэ(н)тёна(н), жё нэ па маль о до́')]),('Слова персонажа',['Слово симптом и описание боли относятся к вымышленному сообщению персонажа. Вопросы проверяют только место и время, не причину состояния.'],[W['symptome']['example']])])
