choose(s,'reading',[A],['il-y-a-ago','vingt','minute','avoir-pc','jai-mal','tete','pendant-duree','dix','maintenant','douleur','dos','depuis','hier','je-voudrais','prendre-rendez-vous','medecin'],['douleur','dos','depuis','jai-mal','tete'],'Какое нынешнее состояние прямо описано в этом сообщении?',fr('Il y a vingt minutes, j’ai eu mal à la tête pendant dix minutes. Maintenant, je n’ai pas mal à la tête. J’ai une douleur au dos depuis hier. Je voudrais prendre rendez-vous avec le médecin.','иль я вэ(н) минют, жэ ю маль а ла тэт па(н)да(н) ди миню́т. мэ(н)тёна(н), жё нэ па маль а ла тэ́т. жэ юн дулёр о до дёпюи йэ́р. жё вудрэ пра(н)др ра(н)дэ ву авэк лё мэдсэ́(н).'),['Голова болит уже двадцать минут, спина не болит','Спина болит со вчерашнего дня, голова сейчас не болит','Никакой боли сейчас не описано'],1,'В сообщении спина болит со вчерашнего дня, голова сейчас не болит.','Двадцать минут назад — время прошлого эпизода головы, десять минут — его длительность. Нынешнее состояние названо отдельно.')
page(s,[('Самоописание и время',['Время эпизода, указанная длительность и продолжающийся период — разные отношения. Место боли и временные слова должны оставаться в своих частях сообщения.'],[W['depuis']['example'],W['il-y-a-ago']['example']]),('Запись и документ',['Время записи не выводят из длительности самоописания. Названный в учебном указании рецепт рассматривается как документ, который просят прочитать или принести.'],[W['cabinet-medical']['example'],W['ordonnance']['example']]),('Уточнить слова',['Просьба повторить помогает уточнить содержание реплики. Упражнения не устанавливают причину состояния, срочность или лечение; нового обязательного материала здесь нет.'],[ex('Répétez, s’il vous plaît.','Повторите, пожалуйста.','рэпэтэ, силь ву плэ́')])])

for s in S:
 required=list(dict.fromkeys(w for t in s['tasks'] for w in t['vocabulary_ids']))
 required+=list(dict.fromkeys(w for i in s['introductions'] for w in i['vocabulary_ids']))
